    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles into shared memory
        int t_offset = t * TILE_SIZE;

        if (row < N && (t_offset + tx) < N) {
