import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for matrix multiplication with register blocking
cuda_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_SIZE 2

__global__ void matrix_mult_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Register block for results
    float c_val[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles into shared memory
        int t_offset = t * TILE_SIZE;

        if (row < N && (t_offset + tx) < N) {
            As[ty][tx] = A[row * N + (t_offset + tx)];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((t_offset + ty) < N && col < N) {
            Bs[ty][tx] = B[(t_offset + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial product using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[ty][k];
            for (int i = 0; i < BLOCK_SIZE; i++) {
                c_val[i][0] += a_val * Bs[k][tx];
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = c_val[0][0];
    }
}

